-- SkillForge proposed relational schema.
-- Design reference only: not a migration and not applied to any database.
-- UUIDs are generated by the application or a separately approved DB extension.

CREATE TABLE organizations (
  id uuid PRIMARY KEY,
  name text NOT NULL,
  slug text NOT NULL,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'deleted')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (slug)
);

CREATE TABLE principals (
  id uuid PRIMARY KEY,
  identity_provider text NOT NULL,
  provider_subject text NOT NULL,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (identity_provider, provider_subject)
);

CREATE TABLE organization_memberships (
  organization_id uuid NOT NULL REFERENCES organizations(id),
  principal_id uuid NOT NULL REFERENCES principals(id),
  role text NOT NULL CHECK (role IN ('owner', 'admin', 'editor', 'reviewer', 'viewer')),
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('invited', 'active', 'suspended', 'removed')),
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (organization_id, principal_id)
);
CREATE INDEX memberships_principal_idx ON organization_memberships (principal_id, status);

CREATE TABLE projects (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL REFERENCES organizations(id),
  slug text NOT NULL,
  name text NOT NULL,
  category_key text NOT NULL,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'archived')),
  current_revision_id uuid,
  created_by uuid NOT NULL REFERENCES principals(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, id),
  UNIQUE (organization_id, slug)
);
CREATE INDEX projects_org_updated_idx ON projects (organization_id, updated_at DESC);

CREATE TABLE project_revisions (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL,
  project_id uuid NOT NULL,
  revision integer NOT NULL CHECK (revision > 0),
  source_brief text NOT NULL,
  category_key text NOT NULL,
  constraints jsonb NOT NULL DEFAULT '[]'::jsonb,
  project_dna jsonb NOT NULL,
  dna_schema_version text NOT NULL,
  assumptions jsonb NOT NULL DEFAULT '[]'::jsonb,
  open_questions jsonb NOT NULL DEFAULT '[]'::jsonb,
  input_hash text NOT NULL,
  created_by uuid NOT NULL REFERENCES principals(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (organization_id, project_id) REFERENCES projects (organization_id, id),
  UNIQUE (project_id, revision),
  UNIQUE (organization_id, id),
  UNIQUE (organization_id, project_id, id)
);
CREATE INDEX project_revisions_project_created_idx ON project_revisions (project_id, created_at DESC);

ALTER TABLE projects
  ADD CONSTRAINT projects_current_revision_fk
  FOREIGN KEY (organization_id, id, current_revision_id)
  REFERENCES project_revisions (organization_id, project_id, id)
  DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE skill_catalogs (
  id uuid PRIMARY KEY,
  visibility text NOT NULL CHECK (visibility IN ('platform', 'organization')),
  organization_id uuid REFERENCES organizations(id),
  catalog_version text NOT NULL,
  status text NOT NULL CHECK (status IN ('draft', 'published', 'deprecated')),
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK ((visibility = 'platform' AND organization_id IS NULL) OR
         (visibility = 'organization' AND organization_id IS NOT NULL)),
  UNIQUE (organization_id, catalog_version)
);
CREATE UNIQUE INDEX platform_catalog_version_idx ON skill_catalogs (catalog_version)
  WHERE organization_id IS NULL;

CREATE TABLE skills (
  id uuid PRIMARY KEY,
  catalog_id uuid NOT NULL REFERENCES skill_catalogs(id),
  slug text NOT NULL,
  tier smallint NOT NULL CHECK (tier BETWEEN 1 AND 7),
  role_name text NOT NULL,
  status text NOT NULL CHECK (status IN ('active', 'deprecated')),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (catalog_id, slug),
  UNIQUE (catalog_id, id)
);

CREATE TABLE skill_versions (
  id uuid PRIMARY KEY,
  skill_id uuid NOT NULL REFERENCES skills(id),
  version text NOT NULL,
  package jsonb NOT NULL,
  schema_version text NOT NULL,
  content_hash text NOT NULL,
  status text NOT NULL CHECK (status IN ('draft', 'published', 'deprecated')),
  provenance jsonb NOT NULL DEFAULT '{}'::jsonb,
  published_by uuid REFERENCES principals(id),
  published_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (skill_id, version),
  UNIQUE (skill_id, id),
  CHECK ((status = 'draft' AND published_at IS NULL) OR
         (status IN ('published', 'deprecated') AND published_at IS NOT NULL))
);
CREATE INDEX skill_versions_eligible_idx ON skill_versions (skill_id, status, published_at DESC);

CREATE TABLE skill_category_memberships (
  skill_id uuid NOT NULL REFERENCES skills(id),
  category_key text NOT NULL,
  applicability jsonb NOT NULL DEFAULT '{}'::jsonb,
  PRIMARY KEY (skill_id, category_key)
);
CREATE INDEX skill_categories_category_idx ON skill_category_memberships (category_key, skill_id);

CREATE TABLE composition_policies (
  id uuid PRIMARY KEY,
  policy_key text NOT NULL,
  version text NOT NULL,
  policy jsonb NOT NULL,
  content_hash text NOT NULL,
  status text NOT NULL CHECK (status IN ('draft', 'published', 'deprecated')),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (policy_key, version)
);

CREATE TABLE template_sets (
  id uuid PRIMARY KEY,
  set_key text NOT NULL,
  version text NOT NULL,
  status text NOT NULL CHECK (status IN ('draft', 'published', 'deprecated')),
  content_hash text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (set_key, version)
);

CREATE TABLE templates (
  id uuid PRIMARY KEY,
  template_set_id uuid NOT NULL REFERENCES template_sets(id),
  logical_key text NOT NULL,
  version text NOT NULL,
  artifact_type text NOT NULL,
  template_body text NOT NULL,
  schema_version text NOT NULL,
  content_hash text NOT NULL,
  status text NOT NULL CHECK (status IN ('draft', 'published', 'deprecated')),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (template_set_id, logical_key, version)
);

CREATE TABLE composition_runs (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL REFERENCES organizations(id),
  project_id uuid NOT NULL,
  project_revision_id uuid NOT NULL,
  parent_run_id uuid,
  catalog_id uuid NOT NULL REFERENCES skill_catalogs(id),
  policy_id uuid NOT NULL REFERENCES composition_policies(id),
  template_set_id uuid NOT NULL REFERENCES template_sets(id),
  generator_version text NOT NULL,
  rubric_version text NOT NULL,
  status text NOT NULL CHECK (status IN (
    'queued', 'understanding', 'composing', 'generating', 'reviewing',
    'revising', 'accepted', 'blocked', 'rejected', 'cancelled', 'failed'
  )),
  stage text,
  attempt integer NOT NULL DEFAULT 0 CHECK (attempt >= 0),
  revision_round integer NOT NULL DEFAULT 0 CHECK (revision_round >= 0),
  idempotency_key text,
  input_hash text NOT NULL,
  graph_hash text,
  accepted_package_hash text,
  state_version integer NOT NULL DEFAULT 0,
  failure_code text,
  failure_detail text,
  created_by uuid NOT NULL REFERENCES principals(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  accepted_at timestamptz,
  FOREIGN KEY (organization_id, project_id) REFERENCES projects (organization_id, id),
  FOREIGN KEY (organization_id, project_id, project_revision_id)
    REFERENCES project_revisions (organization_id, project_id, id),
  FOREIGN KEY (organization_id, parent_run_id)
    REFERENCES composition_runs (organization_id, id),
  UNIQUE (organization_id, id),
  UNIQUE (organization_id, id, catalog_id),
  CHECK ((status = 'accepted' AND accepted_at IS NOT NULL AND accepted_package_hash IS NOT NULL)
      OR status <> 'accepted')
);
CREATE UNIQUE INDEX composition_runs_idempotency_idx
  ON composition_runs (organization_id, idempotency_key)
  WHERE idempotency_key IS NOT NULL;
CREATE INDEX composition_runs_org_status_created_idx
  ON composition_runs (organization_id, status, created_at DESC);
CREATE INDEX composition_runs_project_created_idx
  ON composition_runs (project_id, created_at DESC);

CREATE TABLE run_skill_nodes (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL,
  run_id uuid NOT NULL,
  catalog_id uuid NOT NULL,
  skill_id uuid NOT NULL,
  skill_version_id uuid NOT NULL,
  node_key text NOT NULL,
  priority text NOT NULL CHECK (priority IN ('P0', 'P1', 'P2', 'P3')),
  assigned_scope text NOT NULL,
  selection_score numeric(8, 5) NOT NULL,
  rationale jsonb NOT NULL,
  status text NOT NULL CHECK (status IN ('selected', 'excluded', 'superseded')),
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (organization_id, run_id, catalog_id)
    REFERENCES composition_runs (organization_id, id, catalog_id),
  FOREIGN KEY (catalog_id, skill_id) REFERENCES skills (catalog_id, id),
  FOREIGN KEY (skill_id, skill_version_id) REFERENCES skill_versions (skill_id, id),
  UNIQUE (run_id, node_key),
  UNIQUE (run_id, id)
);
CREATE INDEX run_skill_nodes_run_priority_idx ON run_skill_nodes (run_id, priority, node_key);

CREATE TABLE run_skill_edges (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL,
  run_id uuid NOT NULL,
  source_node_id uuid NOT NULL,
  target_node_id uuid NOT NULL,
  edge_type text NOT NULL CHECK (edge_type IN (
    'depends_on', 'collaborates_with', 'supersedes_scope', 'conflicts_with', 'reviews'
  )),
  origin text NOT NULL CHECK (origin IN ('skill_declaration', 'policy', 'inferred')),
  evidence jsonb NOT NULL,
  resolution jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (organization_id, run_id) REFERENCES composition_runs (organization_id, id),
  FOREIGN KEY (run_id, source_node_id) REFERENCES run_skill_nodes (run_id, id),
  FOREIGN KEY (run_id, target_node_id) REFERENCES run_skill_nodes (run_id, id),
  CHECK (source_node_id <> target_node_id),
  UNIQUE (run_id, source_node_id, target_node_id, edge_type)
);
CREATE INDEX run_skill_edges_target_idx ON run_skill_edges (run_id, target_node_id, edge_type);

CREATE TABLE blueprint_artifacts (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL,
  run_id uuid NOT NULL,
  logical_key text NOT NULL,
  revision integer NOT NULL CHECK (revision > 0),
  artifact_type text NOT NULL,
  media_type text NOT NULL,
  schema_version text NOT NULL,
  template_id uuid REFERENCES templates(id),
  content_text text,
  content_json jsonb,
  object_key text,
  content_hash text NOT NULL,
  status text NOT NULL CHECK (status IN (
    'draft', 'generated', 'under_review', 'accepted', 'superseded', 'invalid'
  )),
  lineage jsonb NOT NULL,
  validation_results jsonb NOT NULL DEFAULT '[]'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (organization_id, run_id) REFERENCES composition_runs (organization_id, id),
  UNIQUE (organization_id, id),
  UNIQUE (run_id, logical_key, revision),
  CHECK (num_nonnulls(content_text, content_json, object_key) = 1)
);
CREATE INDEX blueprint_artifacts_run_key_revision_idx
  ON blueprint_artifacts (run_id, logical_key, revision DESC);
CREATE INDEX blueprint_artifacts_hash_idx ON blueprint_artifacts (content_hash);

CREATE TABLE review_cycles (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL,
  run_id uuid NOT NULL,
  cycle_number integer NOT NULL CHECK (cycle_number >= 0),
  rubric_version text NOT NULL,
  status text NOT NULL CHECK (status IN ('pending', 'in_progress', 'passed', 'failed', 'blocked')),
  overall_score numeric(5, 2),
  gate_decision text CHECK (gate_decision IN ('pass', 'revise', 'block')),
  started_at timestamptz,
  completed_at timestamptz,
  FOREIGN KEY (organization_id, run_id) REFERENCES composition_runs (organization_id, id),
  UNIQUE (organization_id, id),
  UNIQUE (run_id, cycle_number)
);
CREATE INDEX review_cycles_run_status_idx ON review_cycles (run_id, status, cycle_number DESC);

CREATE TABLE reviewer_assessments (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL,
  review_cycle_id uuid NOT NULL,
  reviewer_role text NOT NULL,
  reviewer_kind text NOT NULL CHECK (reviewer_kind IN ('human', 'deterministic', 'model')),
  reviewer_version text NOT NULL,
  score numeric(5, 2),
  status text NOT NULL CHECK (status IN ('pending', 'completed', 'not_applicable', 'failed')),
  rationale text,
  evidence jsonb NOT NULL DEFAULT '[]'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  FOREIGN KEY (organization_id, review_cycle_id)
    REFERENCES review_cycles (organization_id, id),
  UNIQUE (organization_id, id),
  UNIQUE (review_cycle_id, reviewer_role, reviewer_version)
);
CREATE INDEX reviewer_assessments_cycle_status_idx ON reviewer_assessments (review_cycle_id, status);

CREATE TABLE review_findings (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL,
  assessment_id uuid NOT NULL,
  artifact_id uuid,
  severity text NOT NULL CHECK (severity IN ('critical', 'high', 'medium', 'low')),
  status text NOT NULL CHECK (status IN ('open', 'resolved', 'accepted_risk', 'superseded')),
  artifact_pointer text,
  requirement_ref text,
  evidence jsonb NOT NULL,
  acceptance_condition text NOT NULL,
  resolution_evidence jsonb,
  resolved_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (organization_id, assessment_id)
    REFERENCES reviewer_assessments (organization_id, id),
  FOREIGN KEY (organization_id, artifact_id)
    REFERENCES blueprint_artifacts (organization_id, id)
);
CREATE INDEX review_findings_open_severity_idx
  ON review_findings (organization_id, severity, created_at DESC)
  WHERE status = 'open';
CREATE INDEX review_findings_artifact_idx ON review_findings (artifact_id, status);

CREATE TABLE knowledge_sources (
  id uuid PRIMARY KEY,
  organization_id uuid REFERENCES organizations(id),
  source_key text NOT NULL,
  source_type text NOT NULL,
  title text NOT NULL,
  uri text,
  content_hash text,
  usage_rights text,
  approval_status text NOT NULL CHECK (approval_status IN ('pending', 'approved', 'rejected', 'expired')),
  visibility text NOT NULL CHECK (visibility IN ('platform', 'organization')),
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  last_verified_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK ((visibility = 'platform' AND organization_id IS NULL) OR
         (visibility = 'organization' AND organization_id IS NOT NULL)),
  UNIQUE (organization_id, source_key)
);
CREATE UNIQUE INDEX platform_knowledge_source_key_idx ON knowledge_sources (source_key)
  WHERE organization_id IS NULL;
CREATE INDEX knowledge_sources_approved_idx
  ON knowledge_sources (organization_id, approval_status, last_verified_at DESC);

CREATE TABLE run_events (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL,
  run_id uuid NOT NULL,
  sequence_number bigint NOT NULL CHECK (sequence_number > 0),
  event_type text NOT NULL,
  stage text,
  actor_kind text NOT NULL CHECK (actor_kind IN ('system', 'principal', 'worker', 'reviewer')),
  actor_id uuid,
  input_hash text,
  output_hash text,
  details jsonb NOT NULL DEFAULT '{}'::jsonb,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (organization_id, run_id) REFERENCES composition_runs (organization_id, id),
  UNIQUE (run_id, sequence_number)
);
CREATE INDEX run_events_run_sequence_idx ON run_events (run_id, sequence_number);
CREATE INDEX run_events_org_time_idx ON run_events (organization_id, occurred_at DESC);

CREATE TABLE agent_handoffs (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL,
  run_id uuid NOT NULL,
  package_hash text NOT NULL,
  manifest jsonb NOT NULL,
  destination_kind text NOT NULL,
  destination_ref text,
  status text NOT NULL CHECK (status IN ('prepared', 'exported', 'acknowledged', 'failed', 'revoked')),
  requested_by uuid NOT NULL REFERENCES principals(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  exported_at timestamptz,
  acknowledged_at timestamptz,
  FOREIGN KEY (organization_id, run_id) REFERENCES composition_runs (organization_id, id),
  UNIQUE (run_id, package_hash, destination_kind, destination_ref)
);
CREATE INDEX agent_handoffs_org_created_idx ON agent_handoffs (organization_id, created_at DESC);

CREATE TABLE outbox_events (
  id uuid PRIMARY KEY,
  organization_id uuid NOT NULL REFERENCES organizations(id),
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  delivery_attempts integer NOT NULL DEFAULT 0 CHECK (delivery_attempts >= 0)
);
CREATE INDEX outbox_unpublished_idx ON outbox_events (created_at, id)
  WHERE published_at IS NULL;

-- Production implementation must add reviewed RLS policies, tenant-scoped
-- composite foreign keys where needed, append-only permissions/triggers for
-- published/accepted evidence, retention controls, and migration tests.
